:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --key: #0f3460;
  --key-hover: #1a4a7a;
  --key-active: #e94560;
  --display-bg: #0a0a15;
  --font: 'Courier New', Courier, monospace;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

[hidden] { display: none !important; }

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: var(--font);
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 8px;
  padding: 24px 20px;
  width: 100%;
  max-width: 360px;
  box-shadow: 8px 8px 0 rgba(0,0,0,0.5);
  text-align: center;
}

h1 {
  font-size: 1.25rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-bottom: 16px;
  color: var(--accent);
}

.display {
  background: var(--display-bg);
  border: 3px solid var(--key);
  border-radius: 4px;
  padding: 12px;
  font-size: 1.5rem;
  letter-spacing: 4px;
  min-height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  word-break: break-all;
}

.keypad {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.key {
  font-family: var(--font);
  font-size: 1.25rem;
  font-weight: bold;
  padding: 16px 0;
  background: var(--key);
  color: var(--text);
  border: 3px solid var(--accent);
  border-radius: 4px;
  cursor: pointer;
  transition: background 0.1s, transform 0.05s;
  user-select: none;
}

.key:hover { background: var(--key-hover); }
.key:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
.key:active { background: var(--key-active); transform: translate(2px, 2px); }
.key:disabled { opacity: 0.4; cursor: not-allowed; }

.status {
  margin-top: 16px;
  min-height: 24px;
  font-size: 1rem;
  color: var(--accent);
}

.status.unlocked { color: #4ade80; }
.status.wrong { color: var(--accent); }

@media (max-width: 360px) {
  .card { padding: 16px 12px; }
  .key { font-size: 1rem; padding: 12px 0; }
  h1 { font-size: 1rem; }
}

(function () {
  'use strict';

  var CODE = '4271';
  var MAX_ATTEMPTS = 3;
  var LOCKOUT_MS = 10000;

  var buffer = '';
  var wrongAttempts = 0;
  var locked = false;
  var lockTimer = null;
  var countdownTimer = null;

  var display = document.getElementById('display');
  var statusEl = document.getElementById('status');
  var keys = document.querySelectorAll('.key');

  function updateDisplay() {
    display.textContent = buffer || 'Enter code';
  }

  function setStatus(msg, cls) {
    statusEl.textContent = msg;
    statusEl.className = 'status' + (cls ? ' ' + cls : '');
  }

  function setDisabled(disabled) {
    keys.forEach(function (k) { k.disabled = disabled; });
  }

  function startLockout() {
    locked = true;
    setDisabled(true);
    var remaining = LOCKOUT_MS / 1000;
    setStatus('Locked. Try again in ' + remaining + 's', 'wrong');
    countdownTimer = setInterval(function () {
      remaining -= 1;
      if (remaining > 0) {
        setStatus('Locked. Try again in ' + remaining + 's', 'wrong');
      }
    }, 1000);
    lockTimer = setTimeout(function () {
      clearInterval(countdownTimer);
      locked = false;
      wrongAttempts = 0;
      setDisabled(false);
      setStatus('Enter code', '');
      buffer = '';
      updateDisplay();
    }, LOCKOUT_MS);
  }

  function handleDigit(d) {
    if (locked) return;
    if (buffer.length >= 4) return;
    buffer += d;
    updateDisplay();
    setStatus('', '');
  }

  function handleClear() {
    if (locked) return;
    buffer = '';
    updateDisplay();
    setStatus('', '');
  }

  function handleEnter() {
    if (locked) return;
    if (buffer === CODE) {
      setStatus('Unlocked', 'unlocked');
      display.textContent = 'Unlocked';
      buffer = '';
      wrongAttempts = 0;
    } else {
      wrongAttempts += 1;
      setStatus('Wrong code', 'wrong');
      buffer = '';
      updateDisplay();
      if (wrongAttempts >= MAX_ATTEMPTS) {
        startLockout();
      }
    }
  }

  keys.forEach(function (key) {
    key.addEventListener('click', function () {
      if (locked) return;
      var digit = key.getAttribute('data-digit');
      var action = key.getAttribute('data-action');
      if (digit !== null) handleDigit(digit);
      else if (action === 'clear') handleClear();
      else if (action === 'enter') handleEnter();
    });
  });

  document.addEventListener('keydown', function (e) {
    if (locked) return;
    if (e.key >= '0' && e.key <= '9') {
      handleDigit(e.key);
    } else if (e.key === 'Backspace' || e.key === 'Delete') {
      handleClear();
    } else if (e.key === 'Enter') {
      handleEnter();
    }
  });

  updateDisplay();
})();
